document.addEventListener("input",e=>{const t=e.target.closest("[data-bud-rng]");if(!t)return;const k=t.dataset.budRng,v=+t.value,b=B(),p=b.mproj;
 if(k==="rate")b.rate=v;else if(k==="life")b.life=v;else if(k==="grow")b.grow=v;else if(p!=="all"){const m=b.mp[p];m[k]=v;
  if(k==="pre"&&m.pre+m.dev>100){m.dev=100-m.pre;sync("dev",m.dev)}if(k==="dev"&&m.pre+m.dev>100){m.pre=100-m.dev;sync("pre",m.pre)}}
 $$(`[data-bud-val="${k}"]`).forEach(o=>o.textContent=v+(k==="life"?" years":"%"));calcRefresh();
 function sync(kk,vv){const r=$(`[data-bud-rng="${kk}"]`);if(r)r.value=vv;$$(`[data-bud-val="${kk}"]`).forEach(o=>o.textContent=vv+"%")}});
document.addEventListener("change",e=>{const t=e.target.closest("[data-bud-rng]");if(t){audit("changed model assumption",t.dataset.budRng+" = "+t.value);syncM();return}
 const c=e.target.closest("[data-bud-cp]");if(c){const [i,f]=c.dataset.budCp.split(":").map(Number),r=B().cp[B().mproj][i];r[f]=Math.max(0,+c.value||0);audit("changed cost plan",r[0]+" "+(f===2?"FTE ":"months ")+r[f]);render()}});
document.addEventListener("click",e=>{
 let t=e.target.closest("[data-bud-mproj]");if(t){B().mproj=t.dataset.budMproj;render();return}
 t=e.target.closest("[data-bud-scen]");if(t){B().scen=t.dataset.budScen;audit("selected scenario",SCEN[B().scen][0]);render();return}
 t=e.target.closest("[data-bud-sbm]");if(t){B().showMode=t.dataset.budSbm;audit("switched allocation mode",B().showMode);render();return}
 t=e.target.closest("[data-bud-push]");if(t){const l=LN(t.dataset.budPush),lab=laborPlan(l.p);if(lab<l.act){toast("The labor plan is below the "+D$(l.act)+" already paid.","bad");return}audit("pushed labor plan to forecast",l.id+" "+D$(l.fcst)+" to "+D$(lab));l.fcst=lab;toast(l.id+" forecast is now "+D$(lab),"good");render();return}
 t=e.target.closest("[data-bud-addrole]");if(t){roleForm();return}
 t=e.target.closest("[data-bud-runedit]");if(t){runForm();return}
 t=e.target.closest("[data-bud-alloc]");if(t){allocForm(t.dataset.budAlloc);return}});
const RATECARD={"Platform engineer":16000,"Data engineer":16000,"Architect":20000,"Editor subject expert":13000,"Test lead":15000,"Operations engineer":14000,"Project manager":18000};
function roleForm(){const p=B().mproj;if(p==="all")return;
 openF({id:"bud_role",title:"Add a role to "+PJ(p).short,story:"Add people time to the cost plan. The loaded rate comes from the internal rate card, so every project prices the same role the same way.",submit:"Add to cost plan",
 fields:[{k:"role",label:"Role",type:"select",req:true,opts:Object.keys(RATECARD).map(r=>[r,r+" ("+D$(RATECARD[r])+" per FTE-month)"])},{k:"fte",label:"FTE",type:"number",req:true,min:.25,step:.25,help:"1 is one full-time person."},{k:"mo",label:"Months in FY27",type:"number",req:true,min:1,max:12}],defaults:{role:"Test lead",fte:1,mo:3},
 live:v=>liveBox(`<div class="formula">${D$(RATECARD[v.role]||0)} × ${+v.fte||0} FTE × ${+v.mo||0} months = <b>${D$((RATECARD[v.role]||0)*(+v.fte||0)*(+v.mo||0))}</b></div>`),
 onSubmit:v=>{const m=Math.min(12,+v.mo);B().cp[p].push([v.role,RATECARD[v.role],+v.fte,m]);render();return {toast:v.role+" added: "+D$(RATECARD[v.role]*v.fte*m),audit:"added role "+v.role+" to "+p}}})}
function runForm(){const p=B().mproj;if(p==="all")return;const r=B().run[p];
 openF({id:"bud_run",title:"Run costs for "+PJ(p).short,story:"What the new system costs every year after go-live, on top of what the organization already pays. These feed the five-year TCO.",submit:"Save run costs",
 fields:[{k:"cld",label:"Hosting per year",type:"money"},{k:"lic",label:"Licences per year",type:"money"},{k:"sup",label:"Internal support per year",type:"money",help:"For example 0.5 FTE × 12 months × $16,000."},{k:"ven",label:"Vendor support per year",type:"money"}],defaults:{...r},
 live:v=>liveBox(`<div class="formula">Run cost per year = ${D$(+v.cld||0)} + ${D$(+v.lic||0)} + ${D$(+v.sup||0)} + ${D$(+v.ven||0)} = <b>${D$((+v.cld||0)+(+v.lic||0)+(+v.sup||0)+(+v.ven||0))}</b></div>`),
 onSubmit:v=>{B().run[p]={cld:+v.cld||0,lic:+v.lic||0,sup:+v.sup||0,ven:+v.ven||0};render();return {toast:"Run costs saved",audit:"run costs "+p}}})}
function allocForm(p){const rule=B().alloc[p],fx=rule.fixed||USE[p];
 const flds=[{section:"Cost pool"},{k:"p",label:"Project",type:"chips",opts:PROJ.map(x=>[x.id,x.id+" "+x.short])},{k:"driver",label:"Allocation driver",type:"chips",opts:[["usage","Usage report"],["headcount","Headcount"],["equal","Equal split"],["fixed","Fixed percentages"]],help:"Usage reflects who actually uses the service; headcount spreads by people; fixed is a negotiated split."},{section:"Fixed percentages (when selected)"}];
 DEPTS.forEach(d=>flds.push({k:"f_"+d[0],label:d[1],type:"number",min:0,max:100,show:v=>v.driver==="fixed"}));
 const init={p,driver:rule.driver};DEPTS.forEach(d=>init["f_"+d[0]]=fx[d[0]]||0);
 const prev=v=>{const q=v.p||p,old=B().alloc[q];const save=old;B().alloc[q]={driver:v.driver,fixed:Object.fromEntries(DEPTS.map(d=>[d[0],+v["f_"+d[0]]||0]).filter(x=>x[1]))};let pct;try{pct=allocPct(q)}finally{B().alloc[q]=save}return {q,pct}};
 openF({id:"bud_alloc",title:"Allocation rule for "+PJ(p).short,story:"Decide how this project's cost is shared with the departments that benefit. Showback shows the result; chargeback would post it. Percentages always total 100.",submit:"Save rule",fields:flds,defaults:init,
 live:v=>{const {q,pct}=prev(v),f=T(PL(q)).fcst,s=DEPTS.reduce((a,d)=>a+(+v["f_"+d[0]]||0),0);liveBox(`<div class="formula">${Object.keys(pct).map(k=>`${DN(k)} ${pc(pct[k],0)} = ${D$(pct[k]/100*f)}`).join(" · ")}</div>${v.driver==="fixed"&&Math.round(s)!==100?`<div class="small" style="color:var(--bad)">Fixed percentages total ${s}, not 100.</div>`:""}`)},
 onSubmit:v=>{const q=v.p||p;if(v.driver==="fixed"){const s=DEPTS.reduce((a,d)=>a+(+v["f_"+d[0]]||0),0);if(Math.round(s)!==100)return {close:false,toast:"Fixed percentages total "+s+". They must total 100.",audit:"rejected allocation rule"}}
  B().alloc[q]={driver:v.driver,fixed:v.driver==="fixed"?Object.fromEntries(DEPTS.map(d=>[d[0],+v["f_"+d[0]]||0]).filter(x=>x[1])):undefined};render();return {toast:"Allocation rule saved for "+q,audit:q+" driver "+v.driver}}})}
/* ---------- 3. Vendors and contracts ---------- */
const RATES=[["LUM","Senior data engineer",172,158,"per hour"],["LUM","Data engineer",138,131,"per hour"],["LUM","Search engineer",165,160,"per hour"],["LUM","Delivery lead",185,170,"per hour"],["NWC","Compute","118","121","per vCPU block"],["NWC","Object storage",21,22,"per TB-month"],["NWC","Premier support","9%","10%","of monthly spend"],["BRT","Platform engineer",118,109,"per hour"],["BRT","Quality engineer",96,90,"per hour"],["MSF","M365 E5",46.8,47,"per user-month"],["CBL","Penetration tester",220,230,"per hour"]];
const scCls=s=>s>=.85?"good":s>=.75?"warn":"bad";
const mini4=(v,vs)=>[["Delivery",v.del],["Quality",v.qual],["Cost",vs.cost],["Responsiveness",v.resp]].map(x=>`<div class="bud-sc"><span class="small">${x[0]}</span>${meter([{w:x[1]*100,c:`var(--${x[1]>=.85?"s3":x[1]>=.75?"w1":"e4"})`,l:x[0]}])}<b class="tabular small">${x[1].toFixed(2)}</b></div>`).join("");
function vendTile(v){const vs=vScore(v),s=vSpend(v.id),cs=B().con.filter(c=>c.v===v.id);
 return `<button class="card glass bud-vt" data-bud-vend="${v.id}" aria-label="Open ${esc(v.n)}"><div class="row sp" style="flex-wrap:nowrap;align-items:flex-start"><div style="min-width:0"><b style="font-size:18px">${esc(v.n)}</b><div class="small muted">${esc(v.cat)}</div></div><span class="pill ${scCls(vs.sc)}" data-role="metric">${vs.sc.toFixed(2)}${v.new?" new":""}</span></div>
 <div class="bud-scs">${mini4(v,vs)}</div>
 <div><div class="row sp small"><span>Paid ${C$(s.paid)}</span><span class="muted">Committed ${C$(s.ord)}</span></div>${meter([{w:s.paid/Math.max(s.ord,1)*100,c:"var(--p4)",l:"Paid"},{w:(s.inv-s.paid)/Math.max(s.ord,1)*100,c:"var(--w1)",o:.7,l:"Invoiced not paid"}])}</div>
 <div class="row sp small"><span class="muted">${cs.length} contract${cs.length===1?"":"s"} · risk ${v.risk}</span>${spark(v.tr,86,26,col(vs.sc>=.85?"--good-f":vs.sc>=.75?"--warn-f":"--bad-f"))}</div></button>`}
function vendView(){const t=B().vend.map(v=>vScore(v).sc),lum=VID("LUM"),ls=vScore(lum);
 return `${card("How the scorecard is calculated","Four things, weighted. Cost penalizes change orders, billing ahead of accepted work, billing errors and rates above the benchmark.",`<div class="formula" data-role="metric">Scorecard = 0.30 × Delivery + 0.30 × Quality + 0.20 × Cost + 0.20 × Responsiveness<br><span class="small" style="font-style:normal">Cost = max(0, 1 − 2 × change-order % − unearned billing % − 0.05 × billing errors − rate premium %)</span></div>
  <p class="small muted" data-role="story" style="margin:10px 0 0">Worked example, Lumen: 0.30 × ${lum.del.toFixed(2)} + 0.30 × ${lum.qual.toFixed(2)} + 0.20 × ${ls.cost.toFixed(2)} + 0.20 × ${lum.resp.toFixed(2)} = <b>${ls.sc.toFixed(2)}</b>. Cost is ${ls.cost.toFixed(2)} because change orders add ${pc(ls.coP*100,1)} and ${C$(vSpend("LUM").paid-vSpend("LUM").rec)} has been paid ahead of accepted work.</p>`,`<span class="row">${fchip("m_vendor")}${fchip("m_match")}</span>`)}
 <div class="row"><button class="btn primary" data-bud-newvend>New vendor</button><span class="muted small">Scores of 0.85 or more are good, 0.75 to 0.85 need watching, below 0.75 need action.</span></div>
 <div class="grid g3 bud-vgrid">${B().vend.map(vendTile).join("")}</div>`}
const stCon=c=>c.dec?[c.dec,"info"]:daysTo(notice(c))<0?["Notice passed","bad"]:daysTo(notice(c))<=30?["Decide in "+daysTo(notice(c))+" days","bad"]:daysTo(notice(c))<=90?["Decide in "+daysTo(notice(c))+" days","warn"]:["Active","good"];
const conPaid=c=>sum(c.ms.filter(m=>m[3]==="Paid"),m=>m[2]);
function conView(){return `<div class="row"><button class="btn primary" data-bud-newcon>New contract</button><span class="muted small">Select a row for terms, SLAs, obligations, milestones, invoices and POs.</span></div>
 ${wrap(`<table style="min-width:900px"><thead><tr><th>Contract</th><th>Vendor</th><th>Term</th><th>Value</th><th>Paid</th><th>Next renewal event</th><th>Status</th></tr></thead><tbody>${B().con.map(c=>{const s=stCon(c),v=VID(c.v);return `<tr data-bud-ct="${c.id}" tabindex="0" style="cursor:pointer"><td><b>${c.id}</b><span class="sub" style="white-space:normal;min-width:200px">${esc(c.n)}</span></td><td>${esc(v.n)}</td><td class="small">${dshort(c.s)} ${c.s.slice(0,4)} to ${dshort(c.e)} ${c.e.slice(0,4)}</td><td class="tabular">${D$(c.tcv)}${c.co?`<span class="sub">incl. ${D$(c.co)} change order</span>`:""}</td><td class="tabular">${D$(conPaid(c))}<span class="sub">${pc(conPaid(c)/c.tcv*100)} of value</span></td><td class="small">${esc(c.rnTy)}<span class="sub">${dfmt(c.rn)}</span></td><td><span class="pill ${s[1]}">${esc(s[0])}</span></td></tr>`}).join("")}</tbody></table>`)}`}
function renewCal(){const x0=iso(TODAYD),span=365,rows=B().con.filter(inWin).sort((a,b)=>a.rn<b.rn?-1:1),pos=d=>Math.max(0,Math.min(100,(dd(d)-TODAYD)/864e5/span*100));
 const months=Array.from({length:12},(_,i)=>{const d=new Date(Date.UTC(2026,9+i,1));return {l:d.toLocaleDateString("en-US",{month:"short",timeZone:"UTC"}),p:pos(iso(d))}});
 return `<div class="bud-cal" role="img" aria-label="Renewal calendar for the next 12 months"><div class="bud-cal-in"><div class="bud-calh"><span></span><div class="bud-track">${months.map(m=>`<i style="left:${m.p}%">${m.l}</i>`).join("")}</div></div>
 ${rows.map(c=>{const nd=notice(c),dn=daysTo(nd),cls=c.dec?"info":dn<=30?"bad":dn<=90?"warn":"good",l=pos(nd<x0?x0:nd),r=pos(c.rn);return `<div class="bud-calr"><button class="bud-cl" data-bud-ct="${c.id}"><b>${c.id}</b> ${esc(VID(c.v).n)}</button><div class="bud-track"><u style="left:${l}%;width:${Math.max(.6,r-l)}%"></u><span class="bud-mk ${cls}" style="left:${l}%" title="Notice deadline ${dfmt(nd)}">N</span><span class="bud-mk dot" style="left:${r}%" title="${esc(c.rnTy)} ${dfmt(c.rn)}"></span></div></div>`}).join("")}
 <p class="small muted" style="margin:6px 0 0">N is the last day to give notice. The diamond is the renewal or end date.</p></div></div>`}
function alertCard(c){const r=recommend(c),v=VID(c.v),dn=daysTo(notice(c));
 return `<div class="card glass bud-alert"><div class="row sp"><div><div class="eyebrow">${c.id} · ${esc(v.n)} · ${esc(c.rnTy)} ${dfmt(c.rn)}</div><h3 style="font-size:19px">${esc(c.n)}</h3></div><div class="row"><span class="pill ${dn<=30?"bad":dn<=90?"warn":"good"}">Notice by ${dshort(notice(c))} (${dn} days)</span>${c.dec?`<span class="pill info">Decided: ${esc(c.dec)}</span>`:""}</div></div>
 <div class="rem" style="margin-top:10px"><div class="ico">${ico("sparkle")}</div><div style="flex:1"><div class="row"><b>Recommended: <span class="pill ${r.cls}" style="font-size:13px">${r.act}</span></b>${aiChip({model:"Contract Agent",conf:r.conf,title:"Why "+r.act.toLowerCase()+" for "+c.id,src:r.facts,guards:["Recommends only; a person records the decision","Does not send notice to the vendor","Every recommendation is audited"]})}</div><div class="small" data-role="story" style="margin-top:4px">${esc(r.line)}</div><ul class="steps small muted" style="margin:8px 0 0">${r.facts.map(f=>`<li>${esc(f)}</li>`).join("")}</ul></div></div>
 <div class="row" style="margin-top:12px"><button class="btn primary" data-bud-decide="${c.id}">Record decision</button><button class="btn" data-bud-ct="${c.id}">Open contract</button></div></div>`}
function renewView(){const rows=B().con.filter(inWin).sort((a,b)=>notice(a)<notice(b)?-1:1),q=rows.filter(c=>c.rn<="2026-12-31");
 return `${card("Next 12 months","October 2026 to September 2027. "+rows.length+" contracts have a renewal or true-up in this window; "+q.length+" fall in the current quarter (Oct to Dec).",renewCal(),`<span class="row">${fchip("m_renew")}</span>`)}
 <div class="grid g2" style="align-items:start">${rows.map(alertCard).join("")}</div>`}
function sowView(){const sows=B().con.filter(c=>["SOW","Order form","Retainer","Services"].includes(c.ty));
 const prem=RATES.filter(r=>typeof r[2]==="number").map(r=>({r,d:(r[2]-r[3])/r[3]}));
 return `${card("Statements of work and orders","Fixed-price and time-and-materials work, with how much has been paid and what is left.",wrap(`<table style="min-width:760px"><thead><tr><th>SOW</th><th>Vendor</th><th>Fee type</th><th>Value</th><th>Paid</th><th>Remaining</th><th style="min-width:140px">Progress</th></tr></thead><tbody>${sows.map(c=>`<tr data-bud-ct="${c.id}" tabindex="0" style="cursor:pointer"><td><b>${c.id}</b><span class="sub" style="white-space:normal;min-width:180px">${esc(c.n)}</span></td><td>${esc(VID(c.v).n)}</td><td class="small">${esc(c.rate)}</td><td class="tabular">${D$(c.tcv)}</td><td class="tabular">${D$(conPaid(c))}</td><td class="tabular">${D$(c.tcv-conPaid(c))}</td><td>${meter([{w:conPaid(c)/c.tcv*100,c:"var(--p4)",l:"Paid"}])}<span class="small muted">${pc(conPaid(c)/c.tcv*100)}</span></td></tr>`).join("")}</tbody></table>`))}
 ${card("Rate cards against the market benchmark","Benchmark from the procurement index for similar roles and services. Rates more than 5% above are flagged for the next renewal.",wrap(`<table style="min-width:640px"><thead><tr><th>Vendor</th><th>Role or unit</th><th>Our rate</th><th>Benchmark</th><th>Difference</th></tr></thead><tbody>${RATES.map(r=>{const num=typeof r[2]==="number",d=num?(r[2]-r[3])/r[3]:0;return `<tr><td><b>${esc(VID(r[0]).n)}</b></td><td>${esc(r[1])}<span class="sub">${r[4]}</span></td><td class="tabular">${num?"$"+r[2]:esc(r[2])}</td><td class="tabular">${num?"$"+r[3]:esc(r[3])}</td><td>${num?`<span class="pill ${d>.05?"bad":d>0?"warn":"good"}" data-role="metric">${d>0?"+":""}${pc(d*100,1)}</span>`:'<span class="pill good">Better</span>'}</td></tr>`}).join("")}</tbody></table>`),`<span class="small muted">Lumen runs ${pc(sum(prem.filter(x=>x.r[0]==="LUM"),x=>x.d)/4*100,1)} above on average</span>`)}`}
const m3dots=po=>{const a=Math.max(po.ord,po.inv,1);return `<div class="bud-3w" role="img" aria-label="Ordered ${D$(po.ord)}, received ${D$(po.rec)}, invoiced ${D$(po.inv)}">${[["PO",po.ord,"--p4"],["Receipt",po.rec,"--s3"],["Invoice",po.inv,po.inv>po.rec*1.02+1?"--e4":"--w1"]].map(x=>`<div><span class="small muted">${x[0]}</span>${meter([{w:x[1]/a*100,c:`var(${x[2]})`,l:x[0]}])}</div>`).join("")}</div>`};
