function slaRows(c){return c.sla.map(s=>{const hi=s[4],miss=hi?s[2]<s[1]:s[2]>s[1],pcg=hi?Math.min(100,s[2]/s[1]*100):Math.min(100,s[1]/s[2]*100);return `<div class="bud-sc" style="grid-template-columns:minmax(120px,1fr) 1.2fr auto"><span class="small">${esc(s[0])}</span>${meter([{w:pcg,c:miss?"var(--e4)":"var(--s3)",l:s[0]}])}<span class="small tabular"><b>${s[2]}${s[3]}</b> vs ${hi?"≥":"≤"} ${s[1]}${s[3]} ${miss?'<span class="pill bad">Missed</span>':'<span class="pill good">Met</span>'}</span></div>`}).join("")}
function contractDrawer(id){const c=CID(id);if(!c)return;const v=VID(c.v),r=recommend(c),pos=B().po.filter(p=>p.ct===c.id),invs=INVOICES.filter(i=>c.inv.includes(i.id)),s=stCon(c);
 openDrawer(`<span class="pill ${s[1]}">${esc(s[0])}</span><h2 style="font-size:28px;margin:10px 0 4px;padding-right:60px">${esc(c.n)}</h2><p class="muted" data-role="story">${c.id} with ${esc(v.n)}. Owner ${esc(c.own)}. ${c.proj?"Funds project "+PJ(c.proj).short+".":"Paid from "+esc(c.line)+"."}</p>
 <dl class="kv"><dt>Term</dt><dd>${dfmt(c.s)} to ${dfmt(c.e)}</dd><dt>Total value</dt><dd data-role="metric">${D$(c.tcv)}${c.co?` (includes ${D$(c.co)} change order)`:""}</dd><dt>Annual value</dt><dd data-role="metric">${D$(c.ann)}</dd><dt>Paid to date</dt><dd data-role="metric">${D$(conPaid(c))} (${pc(conPaid(c)/c.tcv*100)})</dd><dt>Renewal</dt><dd>${esc(c.rnTy)} ${dfmt(c.rn)}; notice ${c.ntc} days, by ${dfmt(notice(c))}; ${c.auto?"renews automatically":"does not renew automatically"}</dd><dt>Rate basis</dt><dd>${esc(c.rate)}</dd></dl>
 <div class="rem"><div class="ico">${ico("sparkle")}</div><div style="flex:1"><div class="row"><b>Recommended: <span class="pill ${r.cls}">${r.act}</span></b>${aiChip({model:"Contract Agent",conf:r.conf,title:"Why "+r.act.toLowerCase(),src:r.facts})}</div><div class="small" style="margin-top:4px">${esc(r.line)}</div></div></div>
 <div class="eyebrow" style="margin:16px 0 8px">Service levels</div><div class="ledger">${slaRows(c)}</div>
 <div class="eyebrow" style="margin:16px 0 8px">Obligations</div><ul class="steps small">${c.obl.map(o=>`<li><span><b>${esc(o[0])}</b><br><span class="muted">${esc(o[1])} · due ${dfmt(o[2])} ${o[3]?'<span class="pill good">Done</span>':daysTo(o[2])<0?'<span class="pill bad">Overdue</span>':""}</span></span></li>`).join("")}</ul>
 <div class="eyebrow" style="margin:16px 0 8px">Milestones and invoice schedule</div>${wrap(`<table style="min-width:440px"><thead><tr><th>Milestone</th><th>Due</th><th>Amount</th><th>State</th></tr></thead><tbody>${c.ms.map(m=>`<tr><td style="white-space:normal;min-width:180px">${esc(m[0])}</td><td class="small">${dshort(m[1])} ${m[1].slice(0,4)}</td><td class="tabular">${D$(m[2])}</td><td><span class="pill ${m[3]==="Paid"?"good":m[3]==="On hold"||m[3]==="Rejected"?"bad":m[3]==="Scheduled"?"mute":"warn"}">${m[3]}</span></td></tr>`).join("")}</tbody></table>`)}
 ${util(c)}
 <div class="eyebrow" style="margin:16px 0 8px">Linked invoices</div>${invs.length?invs.map(i=>`<button class="need" style="width:100%;text-align:left" data-go="inv:${i.id}"><div class="ico ${i.rec==="approve"?"good":i.rec==="hold"?"warn":"bad"}">${ico(i.rec==="approve"?"check":"warn")}</div><div><b>${i.id} · ${money(i.amt)}</b><span class="muted small" data-role="story">${esc(i.story)}</span></div><span class="pill ${i.rec==="approve"?"good":i.rec==="hold"?"warn":"bad"}">${i.rec}</span></button>`).join(""):'<p class="muted small">No open invoices.</p>'}
 <div class="eyebrow" style="margin:16px 0 8px">Purchase orders</div>${pos.length?pos.map(p=>`<button type="button" class="row sp small bd-n bd-full" data-bd="po:${p.id}" style="padding:6px 0;border-bottom:1px solid var(--hair)"><span><b>${p.id}</b> ${esc(p.d)}</span><span>${D$(p.ord)} · <span class="pill ${m3(p)[1]}">${m3(p)[0]}</span></span></button>`).join(""):'<p class="muted small">No purchase orders yet.</p>'}
 <div class="eyebrow" style="margin:16px 0 8px">Budget</div>${(()=>{const ls=[...new Set([c.proj&&B().lines.find(l=>l.id===c.line)?c.line:"",...pos.map(p=>p.line)].filter(x=>x&&LN(x)))];return ls.length?ls.map(x=>`<button type="button" class="bd-link" data-bd="line:${x}"><b>${x}</b> ${esc(LN(x).n)}<span class="muted small">${C$(LN(x).appr)} approved · ${C$(LN(x).fcst)} forecast</span></button>`).join(""):`<p class="muted small">Paid from ${esc(c.line)}, a run budget outside the project lines.</p>`})()}
 <div class="row" style="margin-top:16px"><button class="btn primary" data-bud-decide="${c.id}">Record renewal decision</button><button class="btn" data-bud-newpo-ct="${c.id}">New purchase order</button></div>`);if(window.BD)BD.after("ct",c.id)}
const util=c=>c.util?`<div class="eyebrow" style="margin:16px 0 8px">Utilization</div><div class="bud-sc" style="grid-template-columns:minmax(120px,1fr) 1.2fr auto"><span class="small">${esc(c.util[0])}</span>${meter([{w:c.util[1]/c.util[2]*100,c:"var(--p4)",l:"Assigned"}])}<b class="small tabular">${c.util[1]} of ${c.util[2]}</b></div>`:"";
function vendorDrawer(id){const v=VID(id),vs=vScore(v),s=vSpend(id),cs=B().con.filter(c=>c.v===id),pos=poV(id);
 openDrawer(`<span class="pill ${scCls(vs.sc)}">Scorecard ${vs.sc.toFixed(2)}</span><h2 style="font-size:28px;margin:10px 0 4px;padding-right:60px">${esc(v.n)}</h2><p class="muted" data-role="story">${esc(v.cat)}. ${esc(v.note)}</p>
 <div class="ledger" style="margin:12px 0">${[["Delivery",v.del,"Milestones and SLAs met on time"],["Quality",v.qual,"Defects and rework found at acceptance"],["Cost",vs.cost,"Change orders "+pc(vs.coP*100,1)+", unearned billing "+pc(vs.unearn*100,1)],["Responsiveness",v.resp,"Time to answer blockers and tickets"]].map(x=>`<div class="lrow"><div class="lbl">${x[0]}<small>${x[2]}</small></div>${meter([{w:x[1]*100,c:`var(--${x[1]>=.85?"s3":x[1]>=.75?"w1":"e4"})`,l:x[0]}])}<div class="amtn num" data-role="metric">${x[1].toFixed(2)}</div></div>`).join("")}</div>
 <div class="formula" data-role="metric">0.30 × ${v.del.toFixed(2)} + 0.30 × ${v.qual.toFixed(2)} + 0.20 × ${vs.cost.toFixed(2)} + 0.20 × ${v.resp.toFixed(2)} = ${vs.sc.toFixed(2)}</div>
 <dl class="kv"><dt>Owner</dt><dd>${esc(v.own)}</dd><dt>Vendor contact</dt><dd>${esc(v.con)}</dd><dt>Risk tier</dt><dd>${v.risk}</dd><dt>Committed</dt><dd data-role="metric">${D$(s.ord)}</dd><dt>Invoiced</dt><dd data-role="metric">${D$(s.inv)}</dd><dt>Paid</dt><dd data-role="metric">${D$(s.paid)}</dd><dt>Accepted work</dt><dd data-role="metric">${D$(s.rec)}</dd></dl>
 <div class="eyebrow" style="margin:12px 0 8px">Last 8 periods</div>${spark(v.tr,420,54,col(vs.sc>=.85?"--good-f":vs.sc>=.75?"--warn-f":"--bad-f"))}
 <div class="eyebrow" style="margin:14px 0 8px">Contracts</div>${cs.map(c=>`<button class="need" style="width:100%;text-align:left" data-bud-ct="${c.id}"><div class="ico info">${ico("book")}</div><div><b>${c.id} · ${D$(c.tcv)}</b><span class="muted small">${esc(c.n)}</span></div><span class="pill ${stCon(c)[1]}">${esc(stCon(c)[0])}</span></button>`).join("")}
 <div class="eyebrow" style="margin:14px 0 8px">Purchase orders</div>${pos.map(p=>`<button type="button" class="row sp small bd-n bd-full" data-bd="po:${p.id}" style="padding:6px 0;border-bottom:1px solid var(--hair)"><span><b>${p.id}</b> ${esc(p.d)}</span><span class="pill ${m3(p)[1]}">${m3(p)[0]}</span></button>`).join("")}
 <div class="eyebrow" style="margin:14px 0 8px">Budget lines paid to this vendor</div>${[...new Set(pos.map(p=>p.line))].filter(x=>LN(x)).map(x=>`<button type="button" class="bd-link" data-bd="line:${x}"><b>${x}</b> ${esc(LN(x).n)}<span class="muted small">${C$(LN(x).appr)} approved · ${C$(LN(x).act)} actual</span></button>`).join("")||'<p class="muted small">Paid from run budgets outside the project lines.</p>'}`);if(window.BD)BD.after("vend",id)}
/* ---- forms ---- */
function vendForm(){openF({id:"bud_nvend",title:"New vendor",story:"Register a vendor before the first purchase order. The risk tier decides which reviews are needed; a new vendor starts with a placeholder scorecard until it has a track record.",submit:"Add vendor",
 fields:[{section:"Who"},{k:"n",label:"Vendor name",type:"text",req:true,ph:"For example Harbor Analytics"},{k:"cat",label:"What they supply",type:"text",req:true,ph:"For example Analytics consulting"},{k:"own",label:"Relationship owner",type:"people",req:true},{k:"con",label:"Vendor contact",type:"text"},
  {section:"Risk and compliance"},{k:"risk",label:"Risk tier",type:"chips",opts:["Low","Medium","High"],req:true,ai:{label:"Suggest tier",fn:v=>/security|cloud|data|identity|hosting/i.test((v.cat||"")+(v.n||""))?"High":/staff|consult/i.test(v.cat||"")?"Medium":"Low"}},{k:"spend",label:"Expected annual spend",type:"money",req:true},{k:"data",label:"Handles Meridian data",type:"toggle"},{k:"ins",label:"Insurance certificate",type:"file",help:"PDF of the current certificate."}],
 defaults:{risk:"Low",spend:50000,data:false},
 live:v=>{const r=whoApproves(+v.spend||0,"Vendor services",v.own,{isNew:true});liveBox(`<div class="rem"><div class="ico">${ico("info")}</div><div><b>First contract of ${D$(+v.spend||0)}: ${esc(r.fname)} approves</b><div class="small muted">${r.revs.map(x=>x.role).join(", ")||"No extra reviews"}.${v.data||v.risk==="High"?" Security and privacy review is required because the vendor touches data or is high risk.":""}</div></div></div>`)},
 onSubmit:v=>{const id=("V"+(B().nx.vn++)),n={id,n:v.n,cat:v.cat,risk:v.risk,own:v.own,con:v.con||"To be added",del:.8,qual:.8,resp:.8,be:0,prem:0,tr:[.8,.8,.8,.8,.8,.8,.8,.8],note:"New vendor. The scorecard is a placeholder until the first deliveries are measured.",new:true};B().vend.push(n);render();return {toast:v.n+" added",audit:"new vendor "+v.n+" tier "+v.risk}}})}
