 const over=po.filter(p=>p.aBy&&p.st!=="Pending approval"&&roleIdx(p.aBy)>=0&&tierIdx(p.ord)>roleIdx(p.aBy));
 out.push({n:"Approver is inside their authority",rule:"The approver's tier must cover the full order value.",ok:!over.length,items:over.map(p=>`${p.id} ${D$(p.ord)} was approved by ${p.aBy}, whose limit is ${upTo(B().doa[roleIdx(p.aBy)].max)}`),fix:over[0]&&over[0].aBy===over[0].cBy?null:over[0]?["data-bud-porr",over[0].id,"Re-route "+over[0].id]:null});
