 const groups={};po.forEach(p=>{const k=p.v+"|"+p.cBy;(groups[k]=groups[k]||[]).push(p)});const splits=[];
 Object.values(groups).forEach(g=>{g=g.sort((a,b)=>a.date<b.date?-1:1);if(g.length<2)return;const w=g.filter(p=>(dd(p.date)-dd(g[0].date))/864e5<=30),s=sum(w,p=>p.ord);if(w.length>1&&tierIdx(s)>Math.max(...w.map(p=>tierIdx(p.ord))))splits.push({w,s})});
 out.push({n:"No split purchases",rule:"Orders to one vendor by one requester within 30 days are added together before choosing the tier.",ok:!splits.length||splits.every(x=>B().sodAck["split:"+x.w[0].id]),items:splits.filter(x=>!B().sodAck["split:"+x.w[0].id]).map(x=>`${x.w.map(p=>p.id).join(", ")} to ${VID(x.w[0].v).n}: ${x.w.length} orders of ${x.w.map(p=>C$(p.ord)).join(", ")} total ${D$(x.s)}, which belongs in tier ${B().doa[tierIdx(x.s)].id}`),fix:splits.find(x=>!B().sodAck["split:"+x.w[0].id])?["data-bud-split",splits.find(x=>!B().sodAck["split:"+x.w[0].id]).w[0].id,"Route as one order to the "+B().doa[tierIdx(splits[0].s)].role]:null});
